/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { NoopAnimationsModule } from '@angular/platform-browser/animations';
import { ActionParamsDialogComponent } from './action-params-dialog.component';
import { ActionParamsOptions } from './action-params-dialog.service';

describe('ActionParamsDialogComponent', () => {
  let ref: jasmine.SpyObj<MatDialogRef<ActionParamsDialogComponent>>;

  const create = (options: Partial<ActionParamsOptions>) => {
    ref = jasmine.createSpyObj<MatDialogRef<ActionParamsDialogComponent>>('MatDialogRef', ['close']);
    TestBed.configureTestingModule({
      imports: [ActionParamsDialogComponent, NoopAnimationsModule],
      providers: [
        { provide: MatDialogRef, useValue: ref },
        { provide: MAT_DIALOG_DATA, useValue: { title: 'T', ok: 'Ok', cancel: 'Back', params: [], ...options } },
      ],
    });
    const fixture = TestBed.createComponent(ActionParamsDialogComponent);
    fixture.detectChanges();
    return fixture.componentInstance;
  };

  afterEach(() => TestBed.resetTestingModule());

  it('does not accept while a required text is blank', () => {
    const dialog = create({ params: [{ name: 'reason', type: 'text', label: 'Reason', required: true }] });

    dialog.form.controls['reason'].setValue('   ');
    dialog.accept();

    expect(dialog.form.invalid).toBeTrue();
    expect(ref.close).not.toHaveBeenCalled();
  });

  it('closes with the values: trimmed texts, numbers, dates and empty as null', () => {
    const dialog = create({
      params: [
        { name: 'reason', type: 'text', label: 'Reason', required: true },
        { name: 'units', type: 'number', label: 'Units' },
        { name: 'at', type: 'date', label: 'At' },
        { name: 'notes', type: 'textarea', label: 'Notes' },
        { name: 'urgent', type: 'boolean', label: 'Urgent' },
      ],
    });

    dialog.form.controls['reason'].setValue('  No budget ');
    dialog.form.controls['units'].setValue('3');
    dialog.form.controls['at'].setValue('2026-11-08');
    dialog.accept();

    expect(ref.close).toHaveBeenCalledWith({
      reason: 'No budget',
      units: 3,
      at: new Date('2026-11-08'),
      notes: null,
      urgent: false,
    });
  });
});
